const storeKey='m11-public-files';
let files=JSON.parse(localStorage.getItem(storeKey)||'[]');
let currentPage='home', hindi=false;
const $=s=>document.querySelector(s);
const content=$('#content');
const pages={
 home:{crumb:'Overview',eyebrow:'BIHAR DEVELOPMENT INTELLIGENCE',title:'A clearer view of Bihar.',desc:'Research, evidence and development insights — brought together in one place.',body:homePage},
 research:{crumb:'Research',eyebrow:'M11 RESEARCH',title:'Ask better questions.',desc:'Explore your documents and build answers that stay connected to evidence.',body:researchPage},
 signals:{crumb:'Signals & archive',eyebrow:'SOURCE INTELLIGENCE',title:'See what’s changing.',desc:'Follow live source feeds, search captured reporting, and trace each headline back to its publisher.',body:signalsPage},
 patterns:{crumb:'Pattern engine',eyebrow:'SIGNAL DETECTION · HEURISTIC',title:'Find a pattern in the timeline.',desc:'Scan approved indicators or archived news coverage for a sharp fall, a quiet consolidation, and a later surge.',body:patternsPage},
 radar:{crumb:'Opportunity & risk radar',eyebrow:'BIHAR-WIDE WATCHTOWER',title:'Pin signals that deserve a closer look.',desc:'Scan reviewed indicator histories for meaningful changes across districts. See the scoring matrix, source evidence, and a cautious next step for every candidate.',body:radarPage},
 eventanalysis:{crumb:'Event analysis',eyebrow:'STRUCTURED ANALYSIS WORKSPACE',title:'Understand an event from several angles.',desc:'Build a sourced, reviewable assessment using systems thinking, feedback loops, uncertainty checks, and competing explanations.',body:eventAnalysisPage},
 library:{crumb:'Source library',eyebrow:'EVIDENCE & SOURCES',title:'Your source library.',desc:'A home for reports, policies and research you can trace back to the page.',body:libraryPage},
 data:{crumb:'Development data',eyebrow:'BIHAR DEVELOPMENT DATA',title:'See the whole picture.',desc:'Explore district indicators with their source and reporting year in view.',body:dataPage},
 catalog:{crumb:'Data catalog',eyebrow:'DATA GOVERNANCE',title:'Know where every value came from.',desc:'Register datasets, retain source details, and review imported indicators before they reach a dashboard.',body:catalogPage},
 graph:{crumb:'Ontology graph',eyebrow:'BIHAR DEVELOPMENT MODEL',title:'Explore connected evidence.',desc:'Trace district observations back to datasets and publishers. Every visible edge is stored with source provenance.',body:graphPage},
 governance:{crumb:'Review & alerts',eyebrow:'HUMAN REVIEW WORKFLOW',title:'Review the evidence.',desc:'Resolve pending indicators and source-health issues before they inform a brief.',body:governancePage},
 policy:{crumb:'Policy studio',eyebrow:'M11 POLICY',title:'Policy, with context.',desc:'Compare schemes, surface evidence and shape clear policy briefs.',body:policyPage},
 monitor:{crumb:'Monitor',eyebrow:'DEVELOPMENT MONITOR',title:'Keep up with what changes.',desc:'Follow new reports and government publications in one considered view.',body:monitorPage},
 studio:{crumb:'Report studio',eyebrow:'M11 STUDIO',title:'Turn research into a report.',desc:'Create clear, source-linked briefs and profiles for review.',body:studioPage},
 private:{crumb:'Private workspace',eyebrow:'BRAiN WORKSPACE',title:'Your team’s private space.',desc:'A secure home for internal research, documents and project work.',body:privatePage}
};
function homePage(){return `<section class="hero hero-immersive"><div class="hero-copy"><div class="hero-kicker"><i></i> M11 / BIHAR SYSTEMS ATLAS</div><div class="hero-index">PUBLIC INTELLIGENCE <span>·</span> 00—01</div><h2>Understand the forces<br><span>shaping Bihar.</span></h2><p>Follow evidence across places, systems and time. Build a clearer view of what is changing — and what still needs to be understood.</p><div class="hero-buttons"><button class="btn btn-primary" data-page="patterns">Explore pattern signals <span>↗</span></button><button class="btn btn-light" data-page="eventanalysis">Open event analysis</button></div></div><div class="hero-art" aria-hidden="true"><div class="hero-world"><svg viewBox="0 0 420 420" class="world-mesh"><defs><radialGradient id="worldGlow" cx="42%" cy="35%"><stop offset="0" stop-color="#a8d9ff" stop-opacity=".55"/><stop offset=".58" stop-color="#7189c8" stop-opacity=".18"/><stop offset="1" stop-color="#17191f" stop-opacity="0"/></radialGradient><linearGradient id="worldStroke" x1="0" x2="1" y1="0" y2="1"><stop stop-color="#b2d8ff" stop-opacity=".82"/><stop offset="1" stop-color="#8c75d8" stop-opacity=".14"/></linearGradient></defs><circle cx="210" cy="210" r="178" fill="url(#worldGlow)"/><circle cx="210" cy="210" r="145" fill="none" stroke="url(#worldStroke)" stroke-width="1.2"/><ellipse cx="210" cy="210" rx="70" ry="145" fill="none" stroke="#b6d8ff" stroke-opacity=".35"/><ellipse cx="210" cy="210" rx="122" ry="145" fill="none" stroke="#b6d8ff" stroke-opacity=".22"/><ellipse cx="210" cy="210" rx="145" ry="52" fill="none" stroke="#b6d8ff" stroke-opacity=".3"/><ellipse cx="210" cy="210" rx="145" ry="100" fill="none" stroke="#b6d8ff" stroke-opacity=".2"/><path d="M76 156C140 186 278 188 344 154M68 242C140 214 280 214 352 245M102 104C155 128 263 129 318 104M107 315C168 286 257 287 311 315" fill="none" stroke="#b9d7ff" stroke-opacity=".26"/><path d="M118 251 170 178 235 214 286 144M170 178 193 275 286 144 308 260M118 251 193 275 235 214 308 260" fill="none" stroke="url(#worldStroke)" stroke-width="1.2"/><g fill="#e2f2ff"><circle cx="118" cy="251" r="4"/><circle cx="170" cy="178" r="5"/><circle cx="235" cy="214" r="4"/><circle cx="286" cy="144" r="5"/><circle cx="193" cy="275" r="3.5"/><circle cx="308" cy="260" r="3"/></g></svg><div class="world-ping ping-a"></div><div class="world-ping ping-b"></div><span class="world-caption">A living map of evidence</span></div><div class="world-label label-a">01 <b>PLACE</b></div><div class="world-label label-b">02 <b>SIGNAL</b></div><div class="world-label label-c">03 <b>CHANGE</b></div></div><div class="hero-scroll">SCROLL TO EXPLORE <span>↓</span></div></section>
 <section class="stat-grid"><div class="stat-card"><div class="stat-top">Tracked sources <span class="stat-icon">▤</span></div><div class="stat-value" id="homeSources">—</div><div class="stat-note">Sources in the source registry</div></div><div class="stat-card"><div class="stat-top">District data coverage <span class="stat-icon">⌖</span></div><div class="stat-value" id="homeDistricts">—</div><div class="stat-note">districts with approved observations</div></div><div class="stat-card"><div class="stat-top">Captured stories <span class="stat-icon">⌕</span></div><div class="stat-value" id="homeResearch">—</div><div class="stat-note">captured across monitored feeds</div></div><div class="stat-card"><div class="stat-top">Review queue <span class="stat-icon">◷</span></div><div class="stat-value" id="homePolicy">—</div><div class="stat-note">imported values awaiting review</div></div></section>
 <section class="section-grid"><div class="panel"><div class="panel-head"><div><h3>Recently added sources</h3><div class="panel-sub">A transparent view of the evidence behind your work.</div></div><button data-page="library">View library →</button></div>${files.length?`<div class="file-list">${files.slice(-3).reverse().map(fileRow).join('')}</div>`:`<div class="empty-state"><div class="empty-symbol">▤</div><b>Your source library is ready</b><p>Add a report or policy document to start building a traceable research collection.</p><button class="btn" data-action="upload">＋ Add a source</button></div>`}</div>
 <div class="panel"><div class="panel-head"><div><h3>Where would you like to begin?</h3><div class="panel-sub">Choose a starting point.</div></div></div><div class="quick-grid"><button class="quick-card" data-page="research"><div class="quick-icon">⌕</div><b>Ask a research question</b><span>Find answers in your sources</span></button><button class="quick-card" data-page="data"><div class="quick-icon">▥</div><b>Explore development data</b><span>Districts and indicators</span></button><button class="quick-card" data-page="policy"><div class="quick-icon">◫</div><b>Review a policy</b><span>Compare evidence and schemes</span></button><button class="quick-card" data-page="studio"><div class="quick-icon">✎</div><b>Draft a report</b><span>Turn findings into a brief</span></button></div></div></section><div class="trust-strip"><span class="trust-icon">✳</span><span><b>Evidence before answers.</b> M11 AI is designed to show what a source says — and where it says it.</span></div>`}
function signalsPage(){return `<div class="signals-toolbar"><div class="signals-state" id="signalsState"><i class="signal-pulse"></i><span><b>Connecting to source desk…</b><small>Checking local archive</small></span></div><div class="signal-actions"><span id="lastUpdated" class="updated-label">Not refreshed yet</span><button class="btn btn-primary" id="refreshSignals">↻ Refresh feeds</button></div></div><div class="signals-layout"><section class="signals-main panel"><div class="signal-tabs"><button class="signal-tab active" data-signal-tab="live">Live signals</button><button class="signal-tab" data-signal-tab="archive">Historical archive</button><button class="signal-tab" data-signal-tab="network">Source map</button></div><div class="signal-filters"><form id="signalSearchForm"><span class="search-icon">⌕</span><input id="signalQuery" placeholder="Search headlines, summaries, or sources…" autocomplete="off"><select id="signalSourceFilter" aria-label="Filter by source"><option value="">All sources</option></select><button class="btn" type="submit">Search</button></form></div><div class="signal-summary" id="signalSummary"><span>Waiting for sources</span><span class="chip">Local archive</span></div><div id="signalResults" class="signal-results"><div class="signal-empty"><div class="empty-symbol">◎</div><b>Starting the source desk</b><p>Connect to the local archive to load live stories and historical captures.</p></div></div></section><aside class="source-rail"><section class="panel source-panel"><div class="panel-head"><div><h3>Source registry</h3><div class="panel-sub"><span id="sourceCount">—</span> tracked sources</div></div><span class="source-orb">◉</span></div><div id="sourceList" class="source-list"><div class="source-skeleton"></div><div class="source-skeleton short"></div></div><details class="source-add"><summary>＋ Add a source</summary><form id="sourceForm"><label>Source name<input name="name" required maxlength="100" placeholder="e.g. Patna city desk"></label><label>Source URL<input name="url" type="url" required placeholder="https://…" spellcheck="false"></label><div class="source-form-row"><label>Type<select name="kind"><option value="feed">RSS / Atom feed</option><option value="bookmark">Web page bookmark</option></select></label><label>Category<select name="category"><option>News</option><option>Government</option><option>Research</option><option>Dataset</option><option>Other</option></select></label></div><button class="btn btn-primary" type="submit">Add to registry</button><small id="sourceFormMessage">Feeds are checked only when you refresh. Bookmarks are saved for reference.</small></form></details></section><section class="panel archive-note"><div class="note-icon">◷</div><div><b>History starts at first capture</b><p>M11 stores feed headlines, publisher excerpts, dates and original links in a local archive. It can’t restore items already removed from a publisher’s feed.</p></div></section></aside></div><div class="trust-strip"><span class="trust-icon">ⓘ</span><span>Publisher pages remain the source of record. M11 archives feed metadata and links, not full newspaper articles.</span></div>`}
function patternsPage(){return `<section class="panel pattern-workbench"><div class="panel-head"><div><h3>Choose a timeline and scan</h3><div class="panel-sub">Each engine looks for a different shape. Review its rule and the underlying series before interpreting a match.</div></div><span class="chip">Explainable heuristics</span></div><div class="pattern-mode"><button class="signal-tab active" data-pattern-mode="indicator">Approved indicator series</button><button class="signal-tab" data-pattern-mode="news">News coverage proxy</button></div><form id="patternForm" class="pattern-controls"><label>Pattern engine<select id="patternType"><option value="drop-rise">Drop → consolidation → rise</option><option value="spike">Sudden spike and reversal</option><option value="trend">Sustained trend</option><option value="level">Lasting level shift</option><option value="volatility">Volatility change</option></select></label><label>District<select id="patternDistrict"><option value="">Select district</option></select></label><label>Dataset<select id="patternDataset"><option value="">Select dataset</option></select></label><label>Indicator<select id="patternIndicator"><option value="">Select indicator</option></select></label><label class="pattern-query" hidden>Headline keyword<input id="patternKeyword" placeholder="e.g. flood, protest, bridge" maxlength="80"></label><button class="btn btn-primary" type="submit">⌕ Scan timeline</button></form><div class="pattern-rules" id="patternRuleDescription">Sharp fall of at least 25%, 2–4 stable periods, then a rise of at least 30%.</div></section><section class="panel pattern-results"><div class="panel-head"><div><h3 id="patternResultTitle">Pattern candidates</h3><div class="panel-sub" id="patternResultNote">Pick a series and run an explainable scan.</div></div><button class="btn" id="savePattern" disabled>Save this scan</button></div><div id="patternChart" class="pattern-chart"><div class="empty-state"><div class="empty-symbol">⌁</div><b>Compare different shapes in the timeline</b><p>Choose an engine and scan a numeric series or captured news coverage.</p></div></div><div id="patternCandidates" class="pattern-candidates"></div></section><section class="panel pattern-history"><div class="panel-head"><div><h3>Previous scans</h3><div class="panel-sub">Saved locally with the input and rules used.</div></div></div><div id="patternHistory"><div class="load-line">Loading saved scans…</div></div></section><div class="trust-strip"><span class="trust-icon">ⓘ</span><span>Matches are heuristic leads, not predictions, causal findings, or proof that an event drove a change. News mode measures mentions in captured RSS headlines/excerpts only; it does not monitor social media or estimate event prevalence.</span></div>`}
function eventAnalysisPage(){const field=(key,label,placeholder='Write notes tied to sources or mark as unknown.')=>`<label class="event-field"><span>${label}</span><textarea data-event-field="${key}" rows="3" placeholder="${placeholder}"></textarea></label>`;return `<section class="panel event-intake"><div class="panel-head"><div><h3>Start with the event</h3><div class="panel-sub">Separate what is known from what is inferred. Add dates and links where possible.</div></div><span class="chip">Human-led analysis</span></div><div class="event-input-grid"><label class="event-field"><span>Event or issue</span><input data-event-field="event" placeholder="What happened?" maxlength="180"></label><label class="event-field"><span>Location</span><input data-event-field="location" placeholder="Place or area" maxlength="180"></label><label class="event-field"><span>Start date or period</span><input data-event-field="time_start" placeholder="YYYY-MM-DD or reporting period" maxlength="80"></label><label class="event-field"><span>End date or period</span><input data-event-field="time_end" placeholder="YYYY-MM-DD or reporting period" maxlength="80"></label><label class="event-field wide"><span>Key question to assess</span><input data-event-field="question" placeholder="What are you trying to understand?" maxlength="240"></label>${field('facts','Observed facts and source links','Brief overview. Add individual sourced claims in the evidence register below.')}</div></section><section class="panel world-record-panel"><div class="panel-head"><div><h3>World-model record</h3><div class="panel-sub">Add typed entities, dated evidence, and explicit relationships. These records can be exported as versioned JSON.</div></div><span class="chip">Structured · source-aware</span></div><div class="event-input-grid"><label class="event-field wide"><span>Entities · one per line: label | type | role</span><textarea data-event-field="wm_entities" rows="4" placeholder="Kosi river | natural_feature | flood source\nSupaul district | place | affected area"></textarea></label><label class="event-field wide"><span>Evidence records · one per line: claim | observed/reported/inferred | source title | URL | date/period | confidence</span><textarea data-event-field="wm_evidence" rows="5" placeholder="River crossed danger mark | observed | Water Resources Dept bulletin | https://… | 2026-07-15 | high"></textarea></label><label class="event-field wide"><span>Relationships · one per line: subject | relation | object | observed/reported/hypothesis | date/period | evidence IDs</span><textarea data-event-field="wm_relations" rows="4" placeholder="Kosi river | flooded | Supaul district | reported | 2026-07-15 | C-1"></textarea></label></div><div class="model-record-note">Keep entity labels consistent across events. Evidence and relationships remain unverified until a reviewer checks the cited source. Invalid lines are preserved in the export under “needs review.” <a href="world-model-event.schema.json" target="_blank" rel="noopener">View the versioned data schema ↗</a></div></section><section class="panel event-method"><div class="panel-head"><div><h3>1 · Map the feedback</h3><div class="panel-sub">Check whether beliefs and actions are reinforcing or correcting conditions on the ground.</div></div><span class="step-mark">01</span></div><div class="event-input-grid">${field('beliefs','Expectations or narratives','What do affected groups believe or expect? Who holds each view?')}${field('actions','Actions that follow','What decisions, behavior, prices, policies, or resource flows change?')}${field('conditions','Underlying conditions','What measurable conditions are changing? Include evidence and time order.')}${field('loop','Possible feedback loop','How could actions change conditions, which then alter expectations? What could break the loop?')}</div></section><section class="panel event-method"><div class="panel-head"><div><h3>2 · Place it in the wider system</h3><div class="panel-sub">Trace drivers and sequence; test for slow-moving pressures and cycle effects.</div></div><span class="step-mark">02</span></div><div class="event-input-grid">${field('drivers','System drivers','Institutions, incentives, resources, policy, technology, demographics, external pressures.')}${field('cycle','Cycle or phase','What appears to be expanding, tightening, accumulating, correcting, or recovering? Cite the indicators.')}${field('analogs','Historical comparisons','What cases are comparable? Note important differences and avoid assuming the same outcome.')}</div></section><section class="panel event-method"><div class="panel-head"><div><h3>3 · Stress-test for fragility and surprises</h3><div class="panel-sub">Look for concentration, dependencies, nonlinear impacts, and actions that remain useful across scenarios.</div></div><span class="step-mark">03</span></div><div class="event-input-grid">${field('exposures','Fragile points and dependencies','What single points of failure, concentrations, or tight couplings could amplify harm?')}${field('tails','Low-frequency, high-impact scenarios','What could be missed by the most likely story? State triggers and plausible consequences, not invented odds.')}${field('resilience','Buffers and robust actions','What preserves options, reduces irreversible downside, or works across multiple explanations?')}</div></section><section class="panel event-method"><div class="panel-head"><div><h3>4 · Compare explanations</h3><div class="panel-sub">Write at least two plausible hypotheses. Record evidence that would weaken your preferred explanation.</div></div><span class="step-mark">04</span></div><div class="event-input-grid">${field('hypothesis_a','Hypothesis A · leading explanation')}${field('hypothesis_b','Hypothesis B · alternative explanation')}${field('hypothesis_c','Hypothesis C · another alternative (optional)')}${field('evidence_matrix','Evidence for and against each','For each hypothesis, list evidence it explains, evidence it does not explain, and what would discriminate between them.')}${field('assumptions','Key assumptions','Which assumptions matter most? What evidence would invalidate each one?')}${field('indicators','Indicators to monitor','Observable signposts, threshold or direction, source, and review date.')}</div></section><section class="panel event-method"><div class="panel-head"><div><h3>5 · Grade the evidence and confidence</h3><div class="panel-sub">Confidence describes the strength of this assessment, not certainty that a forecast will happen.</div></div><span class="step-mark">05</span></div><div class="event-input-grid"><label class="event-field"><span>Confidence in the key judgment</span><select data-event-field="confidence"><option value="">Choose…</option><option>Low</option><option>Moderate</option><option>High</option></select></label>${field('confidence_reason','Why this confidence level?','Consider source quality, corroboration, gaps, and plausible alternatives.')}${field('gaps','Important unknowns and collection gaps','What information is missing, and which source could resolve it?')}</div><div class="event-actions"><button class="btn btn-primary" id="buildEventAssessment" type="button">Build analysis worksheet →</button><button class="btn" id="saveEventDraft" type="button">Save draft in this browser</button><button class="btn" id="loadEventDraft" type="button">Load saved draft</button><button class="btn" id="downloadEventAssessment" type="button" disabled>↓ Download worksheet</button><button class="btn" id="downloadWorldModelRecord" type="button">↓ Export world-model JSON</button><span id="eventDraftStatus">Draft data stays in this browser.</span></div></section><section class="panel event-output"><div class="panel-head"><div><h3>Reviewable assessment</h3><div class="panel-sub">Generated from your entries; no automatic causal claims are added.</div></div><span class="chip">Evidence-led</span></div><div id="eventAssessmentOutput" class="event-assessment-output"><div class="empty-state"><div class="empty-symbol">⊙</div><b>Your worksheet will appear here</b><p>Fill in the prompts above and build the assessment.</p></div></div></section><div class="trust-strip"><span class="trust-icon">ⓘ</span><span>This engine structures analysis; it does not independently verify claims, assign probabilities, or access classified methods. Treat generated output as a working assessment and check every source.</span></div>`}
function radarPage(){return `<section class="panel radar-controls"><div class="panel-head"><div><h3>Run a Bihar-wide scan</h3><div class="panel-sub">Only human-reviewed numeric observations with dated periods are considered.</div></div><button class="btn btn-primary" id="runRadarScan">⌕ Scan approved data</button></div><div class="radar-matrix"><div class="radar-matrix-title"><b>Pinning matrix</b><span>Signals scoring 6+ / 8 are pinned</span></div><div class="radar-matrix-grid"><div><b>Change size</b><span>25% = 1 · 50% = 2</span></div><div><b>Persistence</b><span>One period = 1 · repeated = 2</span></div><div><b>District breadth</b><span>2–4 = 1 · 5+ = 2</span></div><div><b>Evidence</b><span>Source-linked = 1 · 2+ publishers = 2</span></div></div><small>Baseline: median of the previous four periods; candidate also needs a robust deviation. Indicators must be labeled for whether higher or lower is favorable to receive an opportunity or concern label.</small></div><div id="radarScanMessage" class="radar-message">Scan to refresh candidates. A match is a lead for review, not a verified event.</div></section><section class="panel radar-pins"><div class="panel-head"><div><h3>📌 Pinned for attention</h3><div class="panel-sub">Auto-pinned when the visible matrix reaches the threshold. Review evidence before acting.</div></div><span id="radarPinnedCount" class="chip">— pinned</span></div><div id="radarPinnedList"><div class="load-line">Loading pinned signals…</div></div></section><section class="panel radar-watch"><div class="panel-head"><div><h3>Other watch signals</h3><div class="panel-sub">Below the pin threshold or not yet classified.</div></div><span id="radarWatchCount" class="chip">— to review</span></div><div id="radarWatchList"><div class="load-line">Loading watch signals…</div></div></section><div class="trust-strip"><span class="trust-icon">ⓘ</span><span>Scans use approved imported indicator data only. No signal proves causation. News coverage spikes are not treated as danger or opportunity. Pins are stored in this local workspace; this is not a public alert service.</span></div>`}
function fileRow(f){return `<div class="file-row"><span class="file-icon">▤</span><b>${escapeHtml(f.name)}</b><small>${f.size}</small><span class="chip">Added locally</span></div>`}
function researchPage(){return `<div class="chat-layout"><div class="panel chat-main"><div class="panel-head"><div><h3>Research assistant</h3><div class="panel-sub">Ask a question about your uploaded sources.</div></div><span class="chip">${files.length} source${files.length===1?'':'s'}</span></div><div class="chat-messages" id="messages"><div class="message assistant">Hello. I can help you research documents you add here. When connected to the M11 AI service, answers will include source titles and page references. This preview keeps your selected file names in this browser and does not upload them to a server.</div></div><form class="chat-input" id="chatForm"><input id="question" placeholder="Ask about a document or topic…" aria-label="Your research question"><button class="btn btn-primary">Ask <span>→</span></button></form></div><aside class="chat-aside"><h4>Research with confidence</h4><p>Answers should be grounded in the documents you provide. Page citations make it easier to verify every claim.</p><div class="note">AI answering is not connected in this preview. No generated findings or citations will be presented as real.</div><div style="height:15px"></div><button class="chat-prompt" data-fill="Summarize the key findings in my uploaded report.">“Summarize the key findings…”</button><button class="chat-prompt" data-fill="What does this document say about district-level development?">“What does it say about districts?”</button><button class="chat-prompt" data-fill="Compare the recommendations in my sources.">“Compare the recommendations…”</button><button class="btn" data-action="upload" style="margin-top:12px">＋ Add documents</button></aside></div>`}
function libraryPage(){return `<div class="panel"><div class="panel-head"><div><h3>Sources</h3><div class="panel-sub">Documents available in this browser preview.</div></div><button class="btn btn-primary" data-action="upload">＋ Add documents</button></div><div class="upload-zone" id="dropZone"><div class="empty-symbol">↑</div><b>Bring your evidence together</b><p>Choose PDF, DOCX, TXT or CSV files. Files stay in this browser preview; document contents are not uploaded or indexed.</p><button class="btn" data-action="upload">Choose files</button></div><div class="upload-list">${files.length?files.map(fileRow).join(''):`<div class="empty-state"><b>No sources added yet</b><p>Your library will list the files you select here.</p></div>`}</div><div class="trust-strip"><span class="trust-icon">ⓘ</span><span>This preview saves only file names and sizes in local browser storage. It does not read document contents.</span></div></div>`}
function dataPage(){return `<div class="overview-kpis" id="stateKpis"><div class="kpi-skeleton"></div><div class="kpi-skeleton"></div><div class="kpi-skeleton"></div><div class="kpi-skeleton"></div></div><section class="panel state-dashboard"><div class="panel-head"><div><h3>State indicators</h3><div class="panel-sub">A dated official snapshot. Each value retains its reporting period and source.</div></div><a class="btn" href="https://statedata.bihar.gov.in/dataLab/" target="_blank" rel="noopener">Open Bihar DES ↗</a></div><div id="stateIndicatorGrid" class="state-indicator-grid"><div class="load-line">Loading sourced indicators…</div></div><div class="data-provenance" id="stateProvenance"></div></section><section class="panel district-dashboard"><div class="panel-head"><div><h3>District development</h3><div class="panel-sub">District records appear after a sourced CSV is imported and reviewed.</div></div><button class="btn btn-primary" data-page="catalog">＋ Import dataset</button></div><div class="district-controls"><input id="districtSearch" placeholder="Find a district…" aria-label="Find a district"><select id="districtSelect" aria-label="Select district"><option value="">Select district</option></select><span id="districtCoverage" class="chip">Loading district directory</span></div><div id="districtGrid" class="district-grid"></div><div id="districtDetail" class="district-detail"><div class="empty-state"><div class="empty-symbol">⌖</div><b>Select a district</b><p>Open a district profile to inspect its approved indicators and evidence.</p></div></div></section><div class="trust-strip"><span class="trust-icon">ⓘ</span><span>Only reviewed values appear in district profiles. Missing data stays missing; state-level figures are not copied into districts.</span></div>`}
