function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
let patternData={observations:[],stories:[],runs:[]},patternMode='indicator',patternLast=null;
let eventAssessmentMarkdown='';
const eventSectionFields={
 'Event overview':['event','location','time_start','time_end','question','facts'],
 'Feedback and reflexivity':['beliefs','actions','conditions','loop'],
 'System drivers and cycles':['drivers','cycle','analogs'],
 'Fragility, tail risks and resilience':['exposures','tails','resilience'],
 'Competing hypotheses and tests':['hypothesis_a','hypothesis_b','hypothesis_c','evidence_matrix','assumptions','indicators'],
 'Evidence quality and confidence':['confidence','confidence_reason','gaps']
};
const eventFieldLabels={event:'Event or issue',location:'Location',time_start:'Start date or period',time_end:'End date or period',question:'Key question',facts:'Observed facts and source links',beliefs:'Expectations or narratives',actions:'Actions that follow',conditions:'Underlying conditions',loop:'Possible feedback loop',drivers:'System drivers',cycle:'Cycle or phase',analogs:'Historical comparisons',exposures:'Fragile points and dependencies',tails:'High-impact scenarios',resilience:'Buffers and robust actions',hypothesis_a:'Hypothesis A',hypothesis_b:'Hypothesis B',hypothesis_c:'Hypothesis C',evidence_matrix:'Evidence for and against',assumptions:'Key assumptions',indicators:'Indicators to monitor',confidence:'Confidence',confidence_reason:'Confidence rationale',gaps:'Unknowns and collection gaps'};
function initEventAnalysis(){const saved=localStorage.getItem('m11-event-analysis-draft');$('#eventDraftStatus').textContent=saved?'A saved draft is available in this browser.':'Draft data stays in this browser.'}
function eventFields(){return Object.fromEntries([...document.querySelectorAll('[data-event-field]')].map(el=>[el.dataset.eventField,el.value.trim()]))}
function parseWorldLines(text,count,prefix){const records=[],needsReview=[];for(const [i,line] of text.split(/\r?\n/).entries()){if(!line.trim())continue;const parts=line.split('|').map(x=>x.trim());if(parts.length!==count||parts.some(x=>!x)){needsReview.push({line:i+1,raw:line,reason:`Expected ${count} non-empty fields separated by |.`});continue}records.push({id:`${prefix}${records.length+1}`,parts})}return{records,needsReview}}
function worldModelRecord(){
 const v=eventFields(),id=globalThis.crypto?.randomUUID?.()||`event-${Date.now()}`;
 const entityRows=parseWorldLines(v.wm_entities||'',3,'N-'),evidenceRows=parseWorldLines(v.wm_evidence||'',6,'C-'),relationRows=parseWorldLines(v.wm_relations||'',6,'R-');
 const entityMap=new Map(),entities=[],needsReview=[...entityRows.needsReview,...evidenceRows.needsReview,...relationRows.needsReview];
 const slug=s=>String(s).toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||`record-${entities.length+1}`;
 function entity(name,type='unspecified',role=''){
  const norm=String(name).toLowerCase().trim(),known=entityMap.get(`name:${norm}`);if(known)return known;
  const key=`${type.toLowerCase()}:${norm}`;if(!entityMap.has(key)){const entityId=`entity-${slug(type)}-${slug(name)}`;entityMap.set(key,entityId);entityMap.set(`name:${norm}`,entityId);entities.push({id:entityId,label:name,type,role,review_status:'unresolved_identity'})}return entityMap.get(key)
 }
 const eventId=entity(v.event||'Unspecified event','event','assessed event');
 for(const row of entityRows.records){const [name,type,role]=row.parts;entity(name,type,role)}
 const claims=evidenceRows.records.map(row=>{const [claim,classification,title,url,period,confidence]=row.parts,valid=['observed','reported','inferred'].includes(classification.toLowerCase()),conf=['low','moderate','high'].includes(confidence.toLowerCase());if(!valid)needsReview.push({line:row.id,raw:row.parts.join(' | '),reason:'Claim type must be observed, reported, or inferred.'});if(!conf)needsReview.push({line:row.id,raw:row.parts.join(' | '),reason:'Confidence must be low, moderate, or high.'});return{id:row.id,claim,epistemic_status:valid?classification.toLowerCase():'needs_review',source:{title,url,period},confidence:conf?confidence.toLowerCase():null,review_status:'unverified'}});
 const claimIds=new Set(claims.map(c=>c.id));
 const relationships=relationRows.records.map(row=>{const [subject,predicate,object,status,period,refs]=row.parts,valid=['observed','reported','hypothesis'].includes(status.toLowerCase()),evidenceIds=refs.split(',').map(x=>x.trim()).filter(Boolean),unknown=evidenceIds.filter(ref=>!claimIds.has(ref));if(!valid)needsReview.push({line:row.id,raw:row.parts.join(' | '),reason:'Relationship type must be observed, reported, or hypothesis.'});if(unknown.length)needsReview.push({line:row.id,raw:row.parts.join(' | '),reason:`Unknown evidence reference(s): ${unknown.join(', ')}.`});return{id:row.id,subject_id:entity(subject),predicate,object_id:entity(object),epistemic_status:valid?status.toLowerCase():'needs_review',temporal_scope:period,evidence_ids:evidenceIds,confidence:null,review_status:'unverified'}});
 const hypotheses=[['H-A',v.hypothesis_a],['H-B',v.hypothesis_b],['H-C',v.hypothesis_c]].filter(x=>x[1]).map(([hypothesisId,claim])=>({id:hypothesisId,claim,status:'analyst_hypothesis',evidence_comparison_notes:v.evidence_matrix||'',review_status:'unverified'}));
 return{record_type:'m11.world_model.event_assessment',schema_version:'1.0.0',record_id:id,created_at:new Date().toISOString(),review_status:'draft',event:{id:eventId,label:v.event||'Unspecified event',place:v.location||null,temporal_scope:{start:v.time_start||null,end:v.time_end||null},key_question:v.question||null,summary:v.facts||null},entities,claims,relationships,hypotheses,analysis:{feedback:{beliefs:v.beliefs||'',actions:v.actions||'',conditions:v.conditions||'',loop:v.loop||''},system:{drivers:v.drivers||'',cycle:v.cycle||'',historical_analogs:v.analogs||''},resilience:{fragilities:v.exposures||'',tail_scenarios:v.tails||'',robust_actions:v.resilience||''},assumptions:v.assumptions||'',indicators_to_monitor:v.indicators||'',confidence:{level:v.confidence||null,rationale:v.confidence_reason||''},unknowns:v.gaps||''},needs_review}
}
function buildEventAssessment(){const values=eventFields(),filled=Object.values(values).some(Boolean);if(!filled){toast('Add event details before building the worksheet.');return}eventAssessmentMarkdown=`# Event analysis worksheet\n\nGenerated ${new Date().toLocaleString()}\n\n`+Object.entries(eventSectionFields).map(([section,keys])=>`## ${section}\n\n${keys.map(k=>`### ${eventFieldLabels[k]}\n${values[k]||'Not provided.'}`).join('\n\n')}\n`).join('\n')+'\n## Structured evidence register\n\n'+(values.wm_evidence||'No structured evidence entries provided.')+'\n\n## Structured entities\n\n'+(values.wm_entities||'No structured entity entries provided.')+'\n\n## Structured relationships\n\n'+(values.wm_relations||'No structured relationship entries provided.')+'\n\n## Analytic guardrails\n\nThis worksheet organizes the analyst’s inputs. It does not independently verify sources, determine causality, or predict outcomes. Revisit the assessment when monitored indicators change.';$('#eventAssessmentOutput').innerHTML=Object.entries(eventSectionFields).map(([section,keys])=>`<section class="assessment-section"><h4>${escapeHtml(section)}</h4>${keys.map(k=>`<div class="assessment-entry"><b>${escapeHtml(eventFieldLabels[k])}</b><p>${escapeHtml(values[k]||'Not provided.').replace(/\n/g,'<br>')}</p></div>`).join('')}</section>`).join('')+`<section class="assessment-section"><h4>World-model records</h4><div class="assessment-entry"><b>Entities</b><p>${escapeHtml(values.wm_entities||'None added.').replace(/\n/g,'<br>')}</p></div><div class="assessment-entry"><b>Evidence claims</b><p>${escapeHtml(values.wm_evidence||'None added.').replace(/\n/g,'<br>')}</p></div><div class="assessment-entry"><b>Relationships</b><p>${escapeHtml(values.wm_relations||'None added.').replace(/\n/g,'<br>')}</p></div></section><div class="assessment-guardrail">Working assessment built from researcher-provided entries. Check the underlying sources and update the analysis as evidence changes.</div>`;$('#downloadEventAssessment').disabled=false;$('#eventDraftStatus').textContent='Worksheet built. Download it or export a structured JSON record.'}
function saveEventAnalysis(){const draft={saved_at:new Date().toISOString(),fields:eventFields()};localStorage.setItem('m11-event-analysis-draft',JSON.stringify(draft));$('#eventDraftStatus').textContent=`Draft saved in this browser at ${new Date().toLocaleTimeString()}.`;toast('Event analysis draft saved in this browser.')}
function loadEventAnalysis(){const raw=localStorage.getItem('m11-event-analysis-draft');if(!raw){toast('No saved event analysis draft in this browser.');return}try{const draft=JSON.parse(raw);for(const [key,value] of Object.entries(draft.fields||{})){const field=document.querySelector(`[data-event-field="${key}"]`);if(field)field.value=value}$('#eventDraftStatus').textContent=`Loaded local draft saved ${new Date(draft.saved_at).toLocaleString()}.`;toast('Saved event analysis draft loaded.')}catch(e){toast('The saved draft could not be read.')}}
function downloadEventAnalysis(){if(!eventAssessmentMarkdown)buildEventAssessment();if(!eventAssessmentMarkdown)return;const blob=new Blob([eventAssessmentMarkdown],{type:'text/markdown;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='m11-event-analysis.md';a.click();URL.revokeObjectURL(url)}
function downloadWorldModelRecord(){const record=worldModelRecord(),blob=new Blob([JSON.stringify(record,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='m11-world-model-event.json';a.click();URL.revokeObjectURL(url);$('#eventDraftStatus').textContent=`Structured JSON exported · ${record.claims.length} evidence records · ${record.relationships.length} relationships · ${record.needs_review.length} malformed entries flagged.`}
async function loadPatterns(){try{const r=await fetch('/api/patterns/data');if(!r.ok)throw Error('Pattern service unavailable.');patternData=await r.json();fillPatternOptions();renderPatternHistory()}catch(e){$('#patternChart').innerHTML=`<div class="dashboard-offline">${escapeHtml(e.message)} Run <code>python server.py</code>.</div>`}}
function fillPatternOptions(){const districts=[...new Map(patternData.observations.map(x=>[x.district_slug,x.district_name])).entries()];$('#patternDistrict').innerHTML='<option value="">Select district</option>'+districts.map(([s,n])=>`<option value="${escapeHtml(s)}">${escapeHtml(n)}</option>`).join('');$('#patternDataset').innerHTML='<option value="">Select dataset</option>'+[...new Set(patternData.observations.map(x=>x.dataset_name))].sort().map(x=>`<option>${escapeHtml(x)}</option>`).join('');updatePatternIndicators()}
function updatePatternIndicators(){const district=$('#patternDistrict').value,dataset=$('#patternDataset').value;const rows=patternData.observations.filter(x=>(!district||x.district_slug===district)&&(!dataset||x.dataset_name===dataset));$('#patternIndicator').innerHTML='<option value="">Select indicator</option>'+[...new Set(rows.map(x=>x.indicator))].sort().map(x=>`<option>${escapeHtml(x)}</option>`).join('')}
function patternSeries(rows){const map=new Map();for(const row of rows){const p=String(row.period||'').trim();if(!p)continue;const existing=map.get(p);if(!existing||Number(row.id)>Number(existing.id))map.set(p,row)}return [...map.entries()].sort((a,b)=>a[0].localeCompare(b[0],undefined,{numeric:true})).map(([label,row])=>({label,value:Number(row.value_num),row})).filter(p=>Number.isFinite(p.value))}
const patternRules={'drop-rise':'Needs a ≥25% fall, 2–4 following values within an 8% band, and a later ≥30% rise.','spike':'Looks for a ≥30% jump over the prior three-point average followed by a ≥20% retreat within three periods.','trend':'Looks for at least four periods moving broadly in one direction, a ≥20% net change, and a reasonably straight fit.','level':'Compares three periods before and after a possible boundary; flags a ≥25% lasting difference.','volatility':'Compares three-point windows and flags a ≥1.8× increase in standard deviation.'};
function mean(a){return a.reduce((s,x)=>s+x,0)/(a.length||1)}function sd(a){const m=mean(a);return Math.sqrt(mean(a.map(x=>(x-m)**2)))}function reg(points){const ys=points.map(p=>p.value),ym=mean(ys),xm=(ys.length-1)/2,den=ys.reduce((s,_,i)=>s+(i-xm)**2,0),slope=ys.reduce((s,v,i)=>s+(i-xm)*(v-ym),0)/(den||1),ss=ys.reduce((s,v)=>s+(v-ym)**2,0),res=ys.reduce((s,v,i)=>s+(v-(ym+slope*(i-xm)))**2,0);return{slope,r2:ss?1-res/ss:0}}
function scanPattern(points,type='drop-rise'){const out=[];if(type==='drop-rise'){for(let i=2;i<points.length-3;i++){const baseline=Math.max(...points.slice(Math.max(0,i-4),i).map(p=>p.value));if(!(baseline>0))continue;const drop=(baseline-points[i].value)/baseline;if(drop<.25)continue;for(let hold=2;hold<=4&&i+hold<points.length;hold++){const plateau=points.slice(i+1,i+1+hold),vals=plateau.map(p=>p.value),lo=Math.min(...vals),hi=Math.max(...vals),mid=(hi+lo)/2;if(mid<=0||(hi-lo)/mid>.08)continue;const post=points.slice(i+1+hold,i+1+hold+4);if(!post.length)continue;const peak=Math.max(...post.map(p=>p.value)),rise=(peak-points[i].value)/Math.max(Math.abs(points[i].value),.000001);if(rise>=.30){const peakPoint=post.find(p=>p.value===peak);out.push({kind:type,start:i-1,end:points.indexOf(peakPoint),detail:`High ${baseline.toFixed(2)} to trough ${points[i].value.toFixed(2)}: ${(drop*100).toFixed(0)}% fall; ${hold} stable periods; then ${(rise*100).toFixed(0)}% rise to ${peak.toFixed(2)}.`,score:drop+rise});break}}}}
 if(type==='spike'){for(let i=3;i<points.length-1;i++){const base=mean(points.slice(i-3,i).map(p=>p.value)),peak=points[i].value;if(base<=0||peak<base*1.30)continue;const after=points.slice(i+1,i+4),trough=Math.min(...after.map(p=>p.value));if(after.length&&trough<=peak*.80){const j=i+1+after.findIndex(p=>p.value===trough);out.push({kind:type,start:i-1,end:j,detail:`Rose ${(100*(peak/base-1)).toFixed(0)}% above the previous three-period average, then fell ${(100*(peak-trough)/peak).toFixed(0)}% to ${trough.toFixed(2)}.`,score:peak/base-trough/peak})}}}
 if(type==='trend'){for(let i=0;i<=points.length-4;i++){const w=points.slice(i,i+5);if(w.length<4)continue;const {slope,r2}=reg(w),delta=w.at(-1).value-w[0].value,den=Math.max(Math.abs(w[0].value),sd(w));if(Math.abs(delta)/den<.20||r2<.65||Math.sign(delta)!==Math.sign(slope))continue;out.push({kind:type,start:i,end:i+w.length-1,detail:`${delta>0?'Rising':'Falling'} trend: ${w[0].value.toFixed(2)} to ${w.at(-1).value.toFixed(2)} (${(100*delta/Math.max(Math.abs(w[0].value),.000001)).toFixed(0)}% net change); line-fit R² ${(r2).toFixed(2)}.`,score:Math.abs(delta)/den*r2})} }
 if(type==='level'){for(let i=3;i<=points.length-3;i++){const before=points.slice(i-3,i).map(p=>p.value),after=points.slice(i,i+3).map(p=>p.value),a=mean(before),b=mean(after),change=(b-a)/Math.max(Math.abs(a),.000001);if(Math.abs(change)<.25||after.some(v=>Math.sign(v-a)!==Math.sign(b-a)))continue;out.push({kind:type,start:i-1,end:i+2,detail:`Three-period average shifted from ${a.toFixed(2)} to ${b.toFixed(2)} (${(change*100).toFixed(0)}%). The post-boundary values remain on the shifted side.`,score:Math.abs(change)})}}
 if(type==='volatility'){for(let i=3;i<=points.length-3;i++){const before=points.slice(i-3,i).map(p=>p.value),after=points.slice(i,i+3).map(p=>p.value),a=sd(before),b=sd(after);if(a<.000001||b/a<1.8||b<Math.abs(mean(before))*.05)continue;out.push({kind:type,start:i-1,end:i+2,detail:`Three-period standard deviation rose from ${a.toFixed(2)} to ${b.toFixed(2)} (${(b/a).toFixed(1)}×). This signals greater variation, not necessarily greater risk.`,score:b/a})}}
 return out.sort((a,b)=>b.score-a.score).filter((c,i,arr)=>!arr.slice(0,i).some(prev=>Math.abs(prev.start-c.start)<=2&&Math.abs(prev.end-c.end)<=2)).slice(0,8)}
function weeklyNews(keyword){const bins=new Map(),dates=[],rx=new RegExp(keyword.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'i');for(const story of patternData.stories){const date=new Date(story.occurred_at);if(Number.isNaN(date.getTime()))continue;const week=new Date(Date.UTC(date.getUTCFullYear(),date.getUTCMonth(),date.getUTCDate()));week.setUTCDate(week.getUTCDate()-((week.getUTCDay()+6)%7));dates.push(week);if(rx.test(`${story.title||''} ${story.summary||''}`)){const key=week.toISOString().slice(0,10);bins.set(key,(bins.get(key)||0)+1)}}if(!dates.length)return[];const start=Math.min(...dates.map(d=>d.getTime())),end=Math.max(...dates.map(d=>d.getTime())),out=[];for(let t=start;t<=end;t+=7*86400000){const label=new Date(t).toISOString().slice(0,10);out.push({label,value:bins.get(label)||0})}return out}
function drawPattern(points,candidates,unit=''){if(points.length<2){$('#patternChart').innerHTML=`<div class="empty-state"><div class="empty-symbol">⌁</div><b>Not enough dated history</b><p>This engine needs more distinct periods. No values are interpolated.</p></div>`;return}const W=900,H=280,px=48,py=24,vals=points.map(p=>p.value),mn=Math.min(0,...vals),mx=Math.max(...vals),span=mx-mn||1,x=i=>px+i*(W-2*px)/(points.length-1),y=v=>H-py-(v-mn)*(H-2*py)/span,poly=points.map((p,i)=>`${x(i).toFixed(1)},${y(p.value).toFixed(1)}`).join(' '),c=candidates[0];let annotation='';if(c){const left=Math.max(0,c.start),right=Math.min(points.length-1,c.end);annotation=`<rect x="${x(left)-7}" y="${py}" width="${Math.max(14,x(right)-x(left)+14)}" height="${H-2*py}" rx="8" class="pattern-highlight"/>`}const dots=points.map((p,i)=>`<circle cx="${x(i)}" cy="${y(p.value)}" r="4"><title>${escapeHtml(p.label)}: ${p.value} ${escapeHtml(unit)}</title></circle>`).join('');$('#patternChart').innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Timeline chart with detected candidate highlighted"><line x1="${px}" y1="${H-py}" x2="${W-px}" y2="${H-py}" class="chart-axis"/>${annotation}<polyline points="${poly}" class="pattern-line"/>${dots}${points.filter((_,i)=>i===0||i===points.length-1||i%Math.ceil(points.length/7)===0).map(p=>{const i=points.indexOf(p);return `<text x="${x(i)}" y="${H-4}" text-anchor="middle">${escapeHtml(p.label.slice(0,12))}</text>`}).join('')}</svg><div class="pattern-legend"><span>● timeline values (${escapeHtml(unit||'count')})</span><span><i class="candidate-key"></i> detected window</span></div>`}
function runPattern(){const keyword=$('#patternKeyword').value.trim(),type=$('#patternType').value;let points=[],title='',unit='',query={};if(patternMode==='indicator'){const district=$('#patternDistrict').value,dataset=$('#patternDataset').value,indicator=$('#patternIndicator').value;if(!district||!dataset||!indicator){toast('Select district, dataset and indicator first.');return}const rows=patternData.observations.filter(x=>x.district_slug===district&&x.dataset_name===dataset&&x.indicator===indicator);points=patternSeries(rows);unit=rows[0]?.unit||'';title=`${rows[0]?.district_name} · ${indicator}`;query={district,dataset,indicator,unit,source:rows[0]?.publisher||rows[0]?.source_name,source_url:rows[0]?.source_page||rows[0]?.source_url};}else{if(keyword.length<2){toast('Enter a keyword with at least two characters.');return}points=weeklyNews(keyword);title=`News coverage · “${keyword}”`;query={keyword,publisher_scope:'captured RSS/Atom headlines and excerpts'}}query.engine=type;const candidates=scanPattern(points,type);patternLast={mode:patternMode,title,query,points,candidates};const engineName=$('#patternType').selectedOptions[0].textContent;$('#patternResultTitle').textContent=candidates.length?`${candidates.length} ${engineName.toLowerCase()} candidate${candidates.length===1?'':'s'}`:'No matching pattern found';$('#patternResultNote').textContent=`${title} · ${points.length} dated ${patternMode==='news'?'weeks':'periods'} · ${patternRules[type]}`;drawPattern(points,candidates,unit);$('#patternCandidates').innerHTML=candidates.length?candidates.map((c,i)=>`<article class="candidate-row"><span class="candidate-index">0${i+1}</span><div><b>${escapeHtml(engineName)}</b><small>${escapeHtml(c.detail)}</small><small>Window: ${escapeHtml(points[c.start]?.label||'')} through ${escapeHtml(points[c.end]?.label||'')}</small></div><span class="chip">Rule match · inspect</span></article>`).join(''):`<div class="source-empty">${points.length<(type==='drop-rise'||type==='level'||type==='volatility'?6:4)?'Not enough dated history for this scan. Add more comparable periods.':'No window met the selected engine’s rule.'}</div>`;$('#savePattern').disabled=false}
async function savePattern(){if(!patternLast)return;try{const type=patternLast.query.engine;const r=await fetch('/api/patterns/runs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...patternLast,result:{engine:type,candidate_count:patternLast.candidates.length,candidates:patternLast.candidates.map(c=>({detail:c.detail,from:patternLast.points[c.start]?.label,to:patternLast.points[c.end]?.label})),point_count:patternLast.points.length}})});if(!r.ok)throw Error('Could not save scan.');patternData.runs=await (await fetch('/api/patterns/data')).json().then(x=>x.runs);renderPatternHistory();toast('Pattern scan saved.')}catch(e){toast(e.message)}}
function renderPatternHistory(){const box=$('#patternHistory');if(!box)return;box.innerHTML=patternData.runs.length?patternData.runs.map(r=>`<div class="pattern-history-row"><span class="chip">${r.mode==='news'?'News proxy':'Indicator'} · ${escapeHtml(r.result?.engine||'scan')}</span><div><b>${escapeHtml(r.title)}</b><small>${escapeHtml(signalDate(r.created_at))} · ${r.result?.candidate_count??0} candidate(s) · ${r.result?.point_count??0} periods</small>${r.result?.candidates?.slice(0,2).map(c=>`<small>${escapeHtml(c.from||'')} → ${escapeHtml(c.to||'')}: ${escapeHtml(c.detail||'')}</small>`).join('')||''}</div></div>`).join(''):'<div class="source-empty">Saved scans will appear here.</div>'}
let radarSignals=[];
async function loadRadar(){try{const r=await fetch('/api/radar');if(!r.ok)throw Error('Radar service unavailable.');radarSignals=await r.json();renderRadar()}catch(e){$('#radarPinnedList').innerHTML=`<div class="dashboard-offline">${escapeHtml(e.message)} Run <code>python server.py</code>.</div>`}}
function renderRadar(){const pinned=radarSignals.filter(x=>x.status==='pinned'),watch=radarSignals.filter(x=>x.status==='watch');$('#radarPinnedCount').textContent=`${pinned.length} pinned` ;$('#radarWatchCount').textContent=`${watch.length} to review`;const empty='<div class="radar-empty"><span>⌖</span><b>No qualifying signals yet</b><p>Import comparable, dated district data, approve the rows, then run a scan. A minimum four-period baseline plus a new period is required.</p><button class="btn" data-page="catalog">Import district data →</button></div>';$('#radarPinnedList').innerHTML=pinned.length?pinned.map(radarCard).join(''):empty;$('#radarWatchList').innerHTML=watch.length?watch.map(radarCard).join(''):'<div class="source-empty">No lower-scoring candidates are currently on watch.</div>';const matrix=document.querySelector('.radar-matrix');if(matrix){const rule=matrix.querySelector('.radar-matrix-grid>div:last-child span');if(rule)rule.textContent='Source-linked = 1 · 2+ distinct URLs = 2';if(!matrix.querySelector('.radar-direction-help'))matrix.insertAdjacentHTML('beforeend','<small class="radar-direction-help">CSV optional field <code>signal_direction</code>: higher_beneficial, higher_adverse, lower_beneficial, lower_adverse, or neutral (default). Direction is your stated interpretation; the scan does not decide it for you.</small>')}}
function radarCard(s){const category=s.category==='opportunity'?'positive-shift':s.category==='concern'?'concern':'unclassified',label=s.category==='opportunity'?'Potential opportunity':s.category==='concern'?'Potential concern':'Direction not labeled';return `<article class="radar-signal ${category}"><div class="radar-signal-top"><span class="radar-category">${label}</span><span class="radar-score">${s.score}/8 · ${s.status==='pinned'?'PINNED':'WATCH'}</span></div><h4>${escapeHtml(s.title)}</h4><p class="radar-summary">${escapeHtml(s.summary)}</p><div class="radar-meta"><span>${escapeHtml(s.dataset_name)}</span><span>${escapeHtml(s.period)}</span><span>${s.evidence.length} district record(s)</span></div><div class="radar-next"><b>Suggested review</b><p>${escapeHtml(s.recommendation)}</p></div><details class="radar-evidence"><summary>Scoring matrix &amp; source evidence</summary><div class="radar-score-grid">${Object.entries(s.matrix||{}).filter(([k])=>['magnitude','persistence','breadth','evidence'].includes(k)).map(([k,v])=>`<div><b>${escapeHtml(k)} · ${v.score}/${v.max}</b><small>${escapeHtml(v.rule)}</small></div>`).join('')}</div><div class="radar-evidence-list">${s.evidence.map(e=>`<div class="radar-evidence-row"><b>${escapeHtml(e.district)}</b><span>${escapeHtml(String(e.value))} ${escapeHtml(e.unit||'')} vs base ${escapeHtml(String(e.baseline))} (${e.change_pct>0?'+':''}${escapeHtml(String(e.change_pct))}%) · ${escapeHtml(e.publisher||'Publisher not listed')}</span>${e.source_url?`<a href="${escapeHtml(e.source_url)}" target="_blank" rel="noopener">Open source ↗</a>`:''}</div>`).join('')}</div></details><div class="radar-actions">${s.status==='pinned'?`<button class="btn" data-radar-id="${s.id}" data-radar-status="watch">Unpin to watch</button>`:`<button class="btn btn-primary" data-radar-id="${s.id}" data-radar-status="pinned">Pin signal</button>`}<button class="btn" data-radar-id="${s.id}" data-radar-status="dismissed">Dismiss</button></div></article>`}
async function runRadarScan(){const btn=$('#runRadarScan'),msg=$('#radarScanMessage');btn.disabled=true;msg.textContent='Scanning reviewed district histories against the published matrix…';try{const r=await fetch('/api/radar/scan',{method:'POST'}),data=await r.json();if(!r.ok)throw Error(data.error||'Radar scan failed.');radarSignals=data.signals;renderRadar();const pinned=radarSignals.filter(x=>x.status==='pinned').length;msg.textContent=`Scanned ${data.scanned_observations} approved numeric observation(s). ${pinned} signal(s) currently pinned; each is linked to its source records.`}catch(e){msg.textContent=e.message;toast(e.message)}finally{btn.disabled=false}}
async function setRadarStatus(id,status){try{const r=await fetch(`/api/radar/signals/${id}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({status})}),data=await r.json();if(!r.ok)throw Error(data.error||'Could not update signal.');await loadRadar();toast(status==='dismissed'?'Signal dismissed.':status==='pinned'?'Signal pinned.':'Signal moved to watch.')}catch(e){toast(e.message)}}
function render(page=currentPage){currentPage=page;const d=pages[page]||pages.home;$('#crumb').textContent=d.crumb;document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.page===page));content.innerHTML=`<div class="page-enter"><div class="page-head"><div><div class="eyebrow">${d.eyebrow}</div><h1>${d.title}</h1><p>${d.desc}</p></div><div class="head-actions"><button class="btn" data-action="upload">＋ Add a source</button><button class="btn btn-primary" data-page="research">⌕ Ask M11 AI</button></div></div>${d.body()}</div>`;if(page==='signals')loadSignals(true);if(page==='patterns')loadPatterns();if(page==='radar')loadRadar();if(page==='data')loadDashboard();if(page==='catalog')loadCatalog();if(page==='graph')loadGraph();if(page==='governance')loadWorkflows();if(page==='studio')loadReports();if(page==='home')loadHome();if(page==='eventanalysis')initEventAnalysis();}
