// Pointer-following perspective tilt is enabled only for fine pointer devices.
if (matchMedia('(hover:hover) and (pointer:fine)').matches) {
  const tiltSelector = '.hero,.stat-card,.quick-card,.help-card,.workspace-switch,.page-panel,.upload-zone,.chat-aside';
  document.addEventListener('pointermove', event => {
    const card = event.target.closest(tiltSelector);
    if (!card) return;
    const rect = card.getBoundingClientRect();
    const x = (event.clientX - rect.left) / rect.width - .5;
    const y = (event.clientY - rect.top) / rect.height - .5;
    card.style.setProperty('--tilt-x', `${(-y * 3.5).toFixed(2)}deg`);
    card.style.setProperty('--tilt-y', `${(x * 4.5).toFixed(2)}deg`);
  }, {passive:true});
  document.addEventListener('pointerout', event => {
    const card = event.target.closest(tiltSelector);
    if (card && !card.contains(event.relatedTarget)) {
      card.style.removeProperty('--tilt-x');
      card.style.removeProperty('--tilt-y');
    }
  });
}

let signalView='live';
let signalCache=[];
let signalSources=[];
let lastSignalRefresh=0;
let signalsLoading=false;
function signalStatus(kind,title,detail){const box=$('#signalsState');if(!box)return;box.className=`signals-state ${kind||''}`;box.innerHTML=`<i class="signal-pulse"></i><span><b>${escapeHtml(title)}</b><small>${escapeHtml(detail)}</small></span>`}
function signalDate(value){if(!value)return 'Date not provided';const d=new Date(value);return Number.isNaN(d.valueOf())?'Date not provided':d.toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'})}
function renderSourceRegistry(){const list=$('#sourceList');if(!list)return;$('#sourceCount').textContent=signalSources.length;const filter=$('#signalSourceFilter');const selected=filter.value;filter.innerHTML='<option value="">All sources</option>'+signalSources.map(s=>`<option value="${s.id}">${escapeHtml(s.name)}</option>`).join('');if(signalSources.some(s=>String(s.id)===selected))filter.value=selected;list.innerHTML=signalSources.length?signalSources.map(s=>`<div class="source-entry"><span class="source-status ${s.status==='connected'?'connected':s.status==='error'?'error':''}"></span><div class="source-entry-copy"><b>${escapeHtml(s.name)}</b><small>${escapeHtml(s.category)} · ${s.kind==='feed'?'Feed':'Bookmark'}${s.last_checked?` · checked ${escapeHtml(signalDate(s.last_checked))}`:''}</small>${s.error?`<small class="source-error">${escapeHtml(s.error)}</small>`:''}</div><a class="source-open" href="${escapeHtml(s.url)}" target="_blank" rel="noopener noreferrer" aria-label="Open ${escapeHtml(s.name)}">↗</a><button class="source-remove" data-source-delete="${s.id}" title="Remove source" aria-label="Remove ${escapeHtml(s.name)}">×</button></div>`).join(''):'<div class="source-empty">No sources yet. Add an RSS feed or a reference link.</div>'}
function renderStoryList(stories){const box=$('#signalResults');if(!box)return;if(!stories.length){box.innerHTML=`<div class="signal-empty"><div class="empty-symbol">${signalView==='archive'?'◷':'◎'}</div><b>${signalView==='archive'?'No older captures yet':'No stories found'}</b><p>${signalView==='archive'?'Older items will collect here as you refresh feeds over time. Historical stories are available only while publishers retain them in their feeds.':'Refresh your feeds or adjust the search to see current coverage.'}</p></div>`;return}box.innerHTML=stories.map(s=>`<article class="story-card"><div class="story-meta"><span class="story-source">${escapeHtml(s.source_name)}</span><span class="story-category">${escapeHtml(s.source_category||'Source')}</span><time>${escapeHtml(signalDate(s.published_at||s.first_seen))}</time></div><h3><a href="${escapeHtml(s.url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(s.title)}</a></h3>${s.summary?`<p>${escapeHtml(s.summary)}</p>`:''}<div class="story-footer"><span>Captured ${escapeHtml(signalDate(s.first_seen))}</span><a href="${escapeHtml(s.url)}" target="_blank" rel="noopener noreferrer">Open publisher ↗</a></div></article>`).join('')}
function renderSourceMap(stories){const box=$('#signalResults');if(!box)return;const sourceIds=[...new Set(stories.map(s=>s.source_id))].slice(0,7);if(!sourceIds.length){box.innerHTML='<div class="signal-empty"><div class="empty-symbol">⌘</div><b>Map your sources as they come online</b><p>The map will connect each publisher to the headlines it supplied. It shows provenance links only, not inferred relationships between people or organizations.</p></div>';return}const nodes=sourceIds.map((id,i)=>{const source=signalSources.find(s=>s.id===id)||{name:'Source'};const a=(Math.PI*2*i/sourceIds.length)-Math.PI/2;return{id,name:source.name,x:400+Math.cos(a)*190,y:205+Math.sin(a)*112}});const edges=[],storyNodes=[];nodes.forEach((n,ni)=>{const matches=stories.filter(s=>s.source_id===n.id).slice(0,Math.max(1,Math.floor(20/sourceIds.length)));matches.forEach((s,j)=>{const a=(Math.PI*2*(j+.5)/Math.max(matches.length,1))+(ni*.35);const x=n.x+Math.cos(a)*76,y=n.y+Math.sin(a)*55;edges.push(`<line class="map-edge" x1="${n.x}" y1="${n.y}" x2="${x}" y2="${y}"/>`);storyNodes.push(`<g class="map-story"><circle cx="${x}" cy="${y}" r="5"/><title>${escapeHtml(s.title)}</title></g>`)})});box.innerHTML=`<div class="map-key"><span><i class="key-source"></i>Publisher</span><span><i class="key-story"></i>Captured headline</span></div><div class="source-map-wrap"><svg class="source-map" viewBox="0 0 800 410" role="img" aria-label="Map connecting publishers to their captured headlines">${edges.join('')}${storyNodes.join('')}${nodes.map(n=>`<g class="map-publisher"><circle cx="${n.x}" cy="${n.y}" r="20"/><text x="${n.x}" y="${n.y+39}" text-anchor="middle">${escapeHtml(n.name.slice(0,23))}</text></g>`).join('')}</svg></div><p class="map-disclaimer">Connections show which feed supplied each headline. No person, topic, or cause-and-effect links are inferred.</p>`}
async function loadSignals(refresh=false){if(currentPage!=='signals'||signalsLoading)return;signalsLoading=true;const btn=$('#refreshSignals');if(btn&&refresh)btn.disabled=true;signalStatus('loading','Connecting to source desk','Reading configured feeds and local archive…');try{if(refresh){const response=await fetch('/api/refresh',{method:'POST'});if(!response.ok){const body=await response.json().catch(()=>({}));throw new Error(body.error||`Refresh failed (${response.status})`)}const result=await response.json();lastSignalRefresh=Date.now();$('#lastUpdated').textContent=`Updated ${signalDate(result.updated_at)} · ${result.total_archived} archived`;if(result.errors?.length)toast(`${result.errors.length} feed${result.errors.length===1?'':'s'} could not refresh.`)}const [healthRes,sourcesRes]=await Promise.all([fetch('/api/health'),fetch('/api/sources')]);if(!healthRes.ok||!sourcesRes.ok)throw new Error('The source API is unavailable.');const health=await healthRes.json();signalSources=await sourcesRes.json();renderSourceRegistry();const query=$('#signalQuery')?.value.trim()||'';const source=$('#signalSourceFilter')?.value||'';const params=new URLSearchParams({bucket:signalView==='archive'?'archive':'live'});if(query)params.set('q',query);if(source)params.set('source',source);const storiesRes=await fetch(`/api/stories?${params}`);if(!storiesRes.ok)throw new Error('Could not load captured stories.');signalCache=await storiesRes.json();if(signalView==='network')renderSourceMap(signalCache);else renderStoryList(signalCache);$('#signalSummary').innerHTML=`<span><b>${signalCache.length}</b> ${signalView==='archive'?'older captures':'recent feed items'} · <b>${health.stories}</b> total in archive</span><span class="chip">${health.sources} registered sources</span>`;if(!lastSignalRefresh){const latest=signalSources.map(s=>s.last_checked).filter(Boolean).sort().at(-1);if(latest)$('#lastUpdated').textContent=`Last checked ${signalDate(latest)}`;else $('#lastUpdated').textContent='Feeds have not been refreshed'}signalStatus('online','Source desk connected',`Local archive ready · ${health.sources} sources · ${health.stories} captures`)}catch(error){signalStatus('offline','Source service is not connected','Run python server.py to enable live feeds and the local archive.');$('#lastUpdated').textContent='No live connection';$('#sourceCount').textContent='—';$('#sourceList').innerHTML='<div class="source-empty">Connect the local M11 service to manage sources.</div>';$('#signalSummary').innerHTML='<span>Live feed collection is unavailable in this static preview.</span><span class="chip">Needs local service</span>';$('#signalResults').innerHTML=`<div class="signal-empty"><div class="empty-symbol">⌁</div><b>Connect the source service</b><p>${escapeHtml(error.message)} The service fetches RSS/Atom feeds and saves headline history to a local SQLite archive.</p><code>python server.py</code></div>`}finally{signalsLoading=false;if(btn)btn.disabled=false}}
document.addEventListener('click',async e=>{const tab=e.target.closest('[data-signal-tab]');if(tab){signalView=tab.dataset.signalTab;document.querySelectorAll('.signal-tab').forEach(t=>t.classList.toggle('active',t===tab));loadSignals(false);return}if(e.target.closest('#refreshSignals')){loadSignals(true);return}const remove=e.target.closest('[data-source-delete]');if(remove){if(!confirm('Remove this source and its captured archive items?'))return;try{const response=await fetch(`/api/sources/${remove.dataset.sourceDelete}`,{method:'DELETE'});const result=await response.json();if(!response.ok)throw new Error(result.error||'Could not remove source');toast('Source and its captured items removed.');loadSignals(false)}catch(error){toast(error.message)}}});
