async function loadHome(){try{const [dash,sourceList]=await Promise.all([fetch('/api/dashboard').then(r=>r.json()),fetch('/api/sources').then(r=>r.json())]);const stats=Array.isArray(dash.state_observations)?dash.state_observations:[];const covered=dash.districts.filter(d=>d.observation_count>0).length;const values={homeSources:sourceList.length,homeDistricts:`${covered}/38`,homeResearch:dash.stories,homePolicy:dash.pending_reviews};Object.entries(values).forEach(([id,value])=>{const node=$(`#${id}`);if(node)node.textContent=value});}catch{}}
async function loadDashboard(){try{const response=await fetch('/api/dashboard');if(!response.ok)throw new Error('Could not load the Bihar data catalog.');const data=await response.json();const metrics=data.state_observations||[];const byName=name=>metrics.find(x=>x.indicator===name);const kpis=[['GSDP · current prices',byName('GSDP at current prices'),'₹ crore'],['GSDP growth',byName('GSDP growth at current prices'),'%'],['Per-capita income',byName('Per capita income at current prices'),'₹ / person'],['Districts with reviewed data',`${data.districts.filter(d=>d.observation_count>0).length} / ${data.districts.length}`,'districts']];$('#stateKpis').innerHTML=kpis.map(([label,row,unit])=>{const value=typeof row==='string'?row:(row?.value_text??'—');const suffix=typeof row==='string'?unit:(row?.unit||unit);const period=typeof row==='string'?'Coverage':(row?.period||'No published value');return `<div class="state-kpi"><small>${label}</small><b>${escapeHtml(String(value))}</b><span>${escapeHtml(suffix)} · ${escapeHtml(period)}</span></div>`}).join('');$('#stateIndicatorGrid').innerHTML=metrics.map(o=>`<article class="state-indicator"><div class="state-indicator-title">${escapeHtml(o.indicator)}</div><b>${escapeHtml(o.value_text)} <small>${escapeHtml(o.unit)}</small></b><div class="state-indicator-period">${escapeHtml(o.period)}</div><div class="state-indicator-source">Reported by ${escapeHtml(o.publisher||o.source_name)} · captured ${escapeHtml(o.accessed_at)}</div><a href="${escapeHtml(o.source_page||o.source_url)}" target="_blank" rel="noopener">View source ↗</a></article>`).join('');$('#stateProvenance').innerHTML=`Snapshot shown as accessed ${escapeHtml(metrics[0]?.accessed_at||'—')}. Figures preserve the portal’s reported periods; values are not a live API feed. <a href="${escapeHtml(data.data_source)}" target="_blank" rel="noopener">Bihar DES Data Lab ↗</a>`;const districtSelect=$('#districtSelect');const search=$('#districtSearch')?.value||'';districtSelect.innerHTML='<option value="">Select district</option>'+data.districts.map(d=>`<option value="${d.slug}">${escapeHtml(d.name)}</option>`).join('');if(activeDistrict)districtSelect.value=activeDistrict;$('#districtCoverage').textContent=`${data.districts.filter(d=>d.observation_count>0).length} of ${data.districts.length} districts have reviewed indicators`;const visible=data.districts.filter(d=>d.name.toLowerCase().includes(search.toLowerCase()));$('#districtGrid').innerHTML=visible.map(d=>`<button class="district-tile ${d.slug===activeDistrict?'selected':''}" data-select-district="${d.slug}"><b>${escapeHtml(d.name)}</b><span>${d.observation_count?`${d.observation_count} reviewed value${d.observation_count===1?'':'s'}`:'No reviewed values'}</span><i>${d.observation_count?'●':'○'}</i></button>`).join('');if(activeDistrict)loadDistrict(activeDistrict);else $('#districtDetail').innerHTML='<div class="empty-state"><div class="empty-symbol">⌖</div><b>Select a district</b><p>Open a district profile to inspect its approved indicators and evidence.</p></div>';}catch(error){$('#stateKpis').innerHTML=`<div class="dashboard-offline">${escapeHtml(error.message)} Run <code>python server.py</code> for the local data service.</div>`}}
async function loadDistrict(slug){activeDistrict=slug;try{const response=await fetch(`/api/districts/${encodeURIComponent(slug)}`);const result=await response.json();if(!response.ok)throw new Error(result.error||'District not found');$('#districtSelect').value=slug;document.querySelectorAll('[data-select-district]').forEach(node=>node.classList.toggle('selected',node.dataset.selectDistrict===slug));const records=result.observations||[];$('#districtDetail').innerHTML=`<div class="district-detail-head"><div><span class="eyebrow">DISTRICT PROFILE</span><h3>${escapeHtml(result.district.name)}</h3></div><span class="chip">${records.length} reviewed indicator${records.length===1?'':'s'}</span></div>${records.length?`<div class="district-observations">${records.map(o=>`<article class="district-observation"><div><b>${escapeHtml(o.indicator)}</b><small>${escapeHtml(o.period)} · ${escapeHtml(o.dataset_name)}</small></div><strong>${escapeHtml(o.value_text)} <small>${escapeHtml(o.unit)}</small></strong><a href="${escapeHtml(o.source_page||o.source_url)}" target="_blank" rel="noopener">${escapeHtml(o.publisher||o.source_name)} ↗</a></article>`).join('')}</div>`:`<div class="empty-state"><div class="empty-symbol">⌖</div><b>No reviewed indicators for ${escapeHtml(result.district.name)} yet</b><p>Import an official district dataset and review its source before the values appear here.</p><button class="btn" data-page="catalog">Import a district dataset</button></div>`}`}catch(error){$('#districtDetail').innerHTML=`<div class="empty-state"><b>${escapeHtml(error.message)}</b></div>`}}
async function loadCatalog(){try{const response=await fetch('/api/catalog');if(!response.ok)throw new Error('Could not load catalog.');const datasets=await response.json();$('#datasetCount').textContent=`${datasets.length} dataset${datasets.length===1?'':'s'}`;$('#datasetList').innerHTML=datasets.length?datasets.map(d=>`<article class="dataset-row"><span class="dataset-icon">▧</span><div class="dataset-main"><b>${escapeHtml(d.name)}</b><small>${escapeHtml(d.source_name)} · captured ${escapeHtml(signalDate(d.accessed_at))}</small><small>${escapeHtml(d.reporting_period||d.description||'Reporting periods listed per row')}</small></div><div class="dataset-status"><span class="review-badge ${d.status==='approved'?'approved':d.status==='pending'?'pending':''}">${escapeHtml(d.status)}</span><small>${d.approved_count||0} approved · ${d.pending_count||0} pending</small></div><a href="${escapeHtml(d.source_url)}" target="_blank" rel="noopener" aria-label="Open dataset source">↗</a></article>`).join(''):'<div class="empty-state"><b>No datasets yet</b><p>Import a sourced CSV to start the district data catalog.</p></div>'}catch(error){$('#datasetList').innerHTML=`<div class="dashboard-offline">${escapeHtml(error.message)} Run <code>python server.py</code>.</div>`}}
async function loadWorkflows(){try{const [workflowRes,reviewRes]=await Promise.all([fetch('/api/workflows'),fetch('/api/reviews')]);if(!workflowRes.ok||!reviewRes.ok)throw new Error('Workflow service unavailable.');const workflow=await workflowRes.json();const reviews=await reviewRes.json();$('#workflowKpis').innerHTML=`<div class="workflow-kpi"><small>Needs review</small><b>${workflow.pending_reviews}</b><span>indicator observations</span></div><div class="workflow-kpi"><small>Feed issues</small><b>${workflow.failed_sources}</b><span>sources with errors</span></div><div class="workflow-kpi"><small>Refresh due</small><b>${workflow.feeds_needing_refresh}</b><span>feeds older than 24h</span></div>`;$('#workflowTasks').innerHTML=workflow.tasks.length?workflow.tasks.map(t=>`<div class="workflow-task"><span class="task-priority ${t.priority}"></span><div><b>${escapeHtml(t.title)}</b><small>${escapeHtml(t.detail)}</small></div><span class="chip">${escapeHtml(t.type)}</span></div>`).join(''):'<div class="workflow-clear"><span>✓</span><b>Nothing needs attention</b><small>Imported data and tracked feeds are in good standing.</small></div>';$('#reviewCount').textContent=`${reviews.length} pending`;$('#reviewList').innerHTML=reviews.length?reviews.map(r=>`<article class="review-row"><div class="review-main"><div class="review-context"><b>${escapeHtml(r.district_name)}</b><span>${escapeHtml(r.dataset_name)}</span></div><h4>${escapeHtml(r.indicator)}</h4><strong>${escapeHtml(r.value_text)} <small>${escapeHtml(r.unit)}</small></strong><small class="review-period">Period: ${escapeHtml(r.period||'not specified')} · Publisher: ${escapeHtml(r.source_name)}</small><a href="${escapeHtml(r.source_page||r.source_url)}" target="_blank" rel="noopener">Check original source ↗</a></div><div class="review-actions"><button class="btn btn-primary" data-review="${r.id}" data-decision="approved">Approve</button><button class="btn" data-review="${r.id}" data-decision="rejected">Reject</button></div></article>`).join(''):'<div class="empty-state"><div class="empty-symbol">✓</div><b>No observations waiting for review</b><p>Imported CSV data will be held here until a reviewer approves or rejects each row.</p></div>'}catch(error){$('#workflowTasks').innerHTML=`<div class="dashboard-offline">${escapeHtml(error.message)} Run <code>python server.py</code>.</div>`}}
async function loadReports(){try{const [dashRes,reportsRes]=await Promise.all([fetch('/api/dashboard'),fetch('/api/reports')]);if(!dashRes.ok||!reportsRes.ok)throw new Error('Report service unavailable.');const dash=await dashRes.json();const reports=await reportsRes.json();const select=$('#reportDistrict');select.innerHTML='<option value="bihar">Bihar (state)</option>'+dash.districts.map(d=>`<option value="${d.slug}">${escapeHtml(d.name)}</option>`).join('');$('#savedReports').innerHTML=reports.length?reports.map(r=>`<button class="saved-report" data-report-load="${r.id}"><span>▤</span><div><b>${escapeHtml(r.title)}</b><small>${escapeHtml(signalDate(r.created_at))} · ${escapeHtml(r.status)}</small></div><i>↗</i></button>`).join(''):'<div class="source-empty">No drafts saved yet.</div>'}catch(error){$('#savedReports').innerHTML=`<div class="dashboard-offline">${escapeHtml(error.message)} Run <code>python server.py</code>.</div>`}}
async function generateReport(slug){const response=await fetch('/api/reports',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({district_slug:slug})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Could not create report');currentReport=result.content;$('#reportPreview').innerHTML=`<div class="report-preview-head"><b>${escapeHtml(result.title)}</b><span class="review-badge pending">Draft · not published</span></div><pre>${escapeHtml(result.content)}</pre>`;$('#downloadReport').disabled=false;$('#reportMessage').textContent='Draft generated from approved records and captured news links.';toast('Evidence-linked draft created.');loadReports()}
document.addEventListener('change',e=>{if(e.target.id==='csvFile'&&e.target.files[0]){const file=e.target.files[0];const reader=new FileReader();reader.onload=()=>{$('#csvText').value=String(reader.result||'');$('#importMessage').textContent=`Loaded ${file.name}. Check the headers and source details before import.`};reader.onerror=()=>$('#importMessage').textContent='Could not read this CSV file.';reader.readAsText(file)}});
