document.addEventListener('click',async e=>{const district=e.target.closest('[data-select-district]');if(district){loadDistrict(district.dataset.selectDistrict);return}const review=e.target.closest('[data-review]');if(review){const reviewer=$('#reviewerName')?.value.trim()||'';if(!reviewer){toast('Enter a reviewer name before deciding.');$('#reviewerName')?.focus();return}try{const response=await fetch(`/api/reviews/${review.dataset.review}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({decision:review.dataset.decision,reviewer})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Review failed');toast(`Observation ${review.dataset.decision}.`);loadWorkflows()}catch(error){toast(error.message)}return}const saved=e.target.closest('[data-report-load]');if(saved){const response=await fetch(`/api/reports/${saved.dataset.reportLoad}`);const report=await response.json();if(response.ok){currentReport=report.content;$('#reportPreview').innerHTML=`<div class="report-preview-head"><b>${escapeHtml(report.title)}</b><span class="review-badge pending">Draft · not published</span></div><pre>${escapeHtml(report.content)}</pre>`;$('#downloadReport').disabled=false}}});
document.addEventListener('submit',async e=>{if(e.target.id==='datasetImportForm'){e.preventDefault();const form=e.target;const data=Object.fromEntries(new FormData(form).entries());data.csv=$('#csvText').value;$('#importMessage').textContent='Validating source and importing rows…';try{const response=await fetch('/api/imports',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Dataset import failed');$('#importMessage').textContent=`${result.imported} row(s) imported to Review & alerts. ${result.errors.length?result.errors.join(' '):''}`;toast('Dataset stored pending review.');form.reset();$('#csvText').value='';loadCatalog()}catch(error){$('#importMessage').textContent=error.message;toast(error.message)}}if(e.target.id==='reportForm'){e.preventDefault();$('#reportMessage').textContent='Building a sourced draft…';try{await generateReport($('#reportDistrict').value)}catch(error){$('#reportMessage').textContent=error.message;toast(error.message)}}});
document.addEventListener('click',e=>{if(e.target.closest('#downloadReport')&&!e.target.closest('#downloadReport').disabled&&currentReport){const blob=new Blob([currentReport],{type:'text/markdown;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='m11-evidence-brief.md';a.click();URL.revokeObjectURL(url)}});


let graphRecords=[];
let graphLinks=[];
async function loadGraph(){try{const scope=$('#graphScope')?.value||'development';const response=await fetch(`/api/ontology?scope=${encodeURIComponent(scope)}`);if(!response.ok)throw new Error('Ontology service unavailable.');const graph=await response.json();graphRecords=graph.nodes||[];graphLinks=graph.edges||[];$('#graphLegend').innerHTML=(graph.counts||[]).map(c=>`<span><i class="legend-dot ${escapeHtml(c.entity_type.toLowerCase())}"></i>${escapeHtml(c.entity_type)} <b>${c.count}</b></span>`).join('');drawGraph() }catch(error){$('#ontologyCanvas').innerHTML=`<div class="empty-state"><b>${escapeHtml(error.message)}</b><p>Run <code>python server.py</code> to load the local ontology.</p></div>`}}
function drawGraph(){const canvas=$('#ontologyCanvas');if(!canvas)return;if(!graphRecords.length){canvas.innerHTML='<div class="signal-empty"><b>No ontology records</b><p>Register datasets and capture feeds to populate the graph.</p></div>';return}const order=['State','District','Source','Dataset','Scheme','Project','Department','IndicatorObservation','NewsStory'];const groups=order.map(type=>({type,nodes:graphRecords.filter(n=>n.entity_type===type)})).filter(g=>g.nodes.length);const coords=new Map();const colWidth=155;let height=580;groups.forEach((group,col)=>{group.nodes.forEach((node,index)=>coords.set(node.id,{x:100+col*colWidth,y:60+index*38}));height=Math.max(height,group.nodes.length*38+110)});const width=Math.max(980,groups.length*colWidth+110);const edges=graphLinks.filter(e=>coords.has(e.from_entity_id)&&coords.has(e.to_entity_id)).map(edge=>{const a=coords.get(edge.from_entity_id),b=coords.get(edge.to_entity_id),x1=a.x+51,y1=a.y+8,x2=b.x-51,y2=b.y+8,cx=(x1+x2)/2;return `<path class="ontology-edge" d="M ${x1} ${y1} C ${cx} ${y1}, ${cx} ${y2}, ${x2} ${y2}"><title>${escapeHtml(edge.relation_type)} · ${escapeHtml(edge.from_name)} → ${escapeHtml(edge.to_name)}${edge.source_url?' · '+escapeHtml(edge.source_url):''}</title></path>`}).join('');const columns=groups.map((g,i)=>`<text class="ontology-column-label" x="${100+i*colWidth}" y="25" text-anchor="middle">${escapeHtml(g.type)} · ${g.nodes.length}</text>`).join('');const nodes=groups.flatMap(g=>g.nodes.map(node=>{const p=coords.get(node.id);return `<g class="ontology-node ${escapeHtml(node.entity_type.toLowerCase())}" data-entity-id="${node.id}" tabindex="0" role="button" aria-label="${escapeHtml(node.entity_type)}: ${escapeHtml(node.name)}"><rect x="${p.x-53}" y="${p.y-12}" width="106" height="24" rx="7"></rect><circle cx="${p.x-42}" cy="${p.y}" r="3"></circle><text x="${p.x-34}" y="${p.y+3}">${escapeHtml(node.name.length>18?node.name.slice(0,17)+'…':node.name)}</text><title>${escapeHtml(node.entity_type)}: ${escapeHtml(node.name)}</title></g>`})).join('');canvas.innerHTML=`<svg class="ontology-svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" role="img" aria-label="Ontology graph with ${graphRecords.length} records and ${graphLinks.length} verified links">${columns}${edges}${nodes}</svg>`}
function showEntity(id){const node=graphRecords.find(n=>n.id===Number(id));if(!node)return;let properties={};try{properties=JSON.parse(node.properties_json||'{}')}catch{}const links=graphLinks.filter(e=>e.from_entity_id===node.id||e.to_entity_id===node.id);$('#entityDetail').innerHTML=`<span class="chip">${escapeHtml(node.entity_type)}</span><h3>${escapeHtml(node.name)}</h3><p class="entity-slug">${escapeHtml(node.slug)}</p><div class="entity-properties">${Object.entries(properties).length?Object.entries(properties).map(([k,v])=>`<div><small>${escapeHtml(k.replaceAll('_',' '))}</small><b>${escapeHtml(String(v))}</b></div>`).join(''):'<small>No extra properties</small>'}</div><div class="entity-links"><b>${links.length} verified link${links.length===1?'':'s'}</b>${links.map(e=>`<div>${escapeHtml(e.from_entity_id===node.id?e.relation_type:'← '+e.relation_type)} · ${escapeHtml(e.from_entity_id===node.id?e.to_name:e.from_name)}</div>`).join('')||'<small>No verified links yet.</small>'}</div>`}
document.addEventListener('change',e=>{if(e.target.id==='graphScope')loadGraph()});
document.addEventListener('click',e=>{if(e.target.closest('#refreshGraph'))loadGraph();const node=e.target.closest('[data-entity-id]');if(node){document.querySelectorAll('.ontology-node.selected').forEach(n=>n.classList.remove('selected'));node.classList.add('selected');showEntity(node.dataset.entityId)}});
